namespace {float number(jass::Real v){return std::bit_cast<float>(v.bits());}}
void ScriptSession::awardExperience(std::uint32_t killer,const UnitState& victim) {
    if(victim.illusion || !alive(killer,NativeKind::Unit) || (victim.building && gameplayNumber("BuildingKillsGiveExp",0)==0))return;auto source=units_.at(killer);auto owner=source->owner;if(!enemy(owner,victim.owner))return;bool creep=victim.owner==12;auto key=victim.hero?"GrantHeroXP":"GrantNormalXP";std::vector<double> values;std::stringstream list(gameplay().value("Misc",key));std::string part;while(std::getline(list,part,',')){double value=std::stod(part);if(!std::isfinite(value) || value<0)throw std::runtime_error("Invalid source kill experience table");values.push_back(value);}unsigned level=unsigned(std::clamp(victim.level,1,10000));if(values.empty())throw std::runtime_error("Missing source kill experience table");double a=gameplayNumber((std::string(key)+"FormulaA").c_str(),1),b=gameplayNumber((std::string(key)+"FormulaB").c_str(),0),c=gameplayNumber((std::string(key)+"FormulaC").c_str(),0);while(values.size()<level){double value=a*values.back()+b*double(values.size()+1)+c;if(!std::isfinite(value) || value<0 || value>INT_MAX)throw std::runtime_error("Kill experience formula exceeds budget");values.push_back(value);}double amount=values[level-1]*(victim.typeFlag(10,victim.summoner!=0)?gameplayNumber("SummonedKillFactor",.5f):1);float radius=gameplayNumber("HeroExpRange",1200);std::vector<std::uint32_t> recipients,fallback;for(auto& [id,u]:units_)if(u->hero && !u->illusion && !u->removing && number(u->life)>0 && (u->owner==owner || (config_.players[owner].alliances[u->owner]&(1u<<4)))){if(u->owner==owner)fallback.push_back(id);bool elemental=source->spiritParent==id && u->spiritSplit && u->spiritSplit->ticket==source->spiritTicket && u->spiritSplit->owner==owner;if(elemental || std::hypot(number(u->x)-number(victim.x),number(u->y)-number(victim.y))<=radius)recipients.push_back(id);}if(recipients.empty() && gameplayNumber("GlobalExperience",1)!=0)recipients=std::move(fallback);if(recipients.empty())return;unsigned maximum=unsigned(heroThresholds().size());if(gameplayNumber("MaxLevelHeroesDrainExp",1)==0)std::erase_if(recipients,[&](auto id){return units_.at(id)->level>=int(maximum);});if(recipients.empty())return;std::vector<double> factors;std::stringstream factorList(gameplay().value("Misc","HeroFactorXP"));while(std::getline(factorList,part,','))factors.push_back(std::stod(part));for(auto id:recipients){if(!alive(id,NativeKind::Unit))continue;auto hero=units_.at(id);if(hero->experienceSuspended || hero->level>=int(maximum))continue;double value=amount/recipients.size();if(creep && !factors.empty())value*=factors[std::min(size_t(std::max(1,hero->level)-1),factors.size()-1)]/100;value*=number(config_.players[hero->owner].handicapXP);if(!std::isfinite(value) || value<0)throw std::runtime_error("Invalid shared experience amount");int xp=int(std::min(double(INT_MAX),double(hero->experience)+std::floor(value)));heroExperience(id,xp);}
}
